function ExperienceSection({
  title,
  items,
}: {
  title: string;
  items: {
    image: string;
    title: string;
    subtitle?: string;
  }[];
}) {
  return (
    <section className="home-section">
      <div className="section-heading-row">
        <h2>{title}</h2>

        <button className="section-arrow" aria-label="Next">
          →
        </button>
      </div>

      <div className="experience-scroll">
        {items.map((item) => (
          <article className="experience-card" key={item.title}>
            <div className="experience-image-wrapper">
              <img
                src={item.image}
                alt={item.title}
                className="experience-image"
                loading="lazy"
              />

              <button className="experience-heart">♡</button>
            </div>

            <h3>{item.title}</h3>

            {item.subtitle && <p>{item.subtitle}</p>}
          </article>
        ))}
      </div>
    </section>
  );
}

